10	/**
11	 * The account's model entitlement right now. A plan entitles its PAID tier while the paid
12	 * period runs (also after cancel, until the period ends), plus `pastDueGraceDays` while
13	 * Stripe retries a failed renewal. An admin override can only raise it.
14	 */
15	export function effectiveTier(input: { plan: PlanState; override?: string | null; overrideUntil?: Date | null; now: Date; cfg: TokenConfig }): TokenTier {
16	  const { plan, now, cfg } = input;
17	  let tier: TokenTier = "free";
18	  if (plan && (plan.tier === "katara" || plan.tier === "saka" || plan.tier === "all") && plan.currentPeriodEnd) {
19	    const end = plan.currentPeriodEnd.getTime();
20	    const ok =
21	      ["active", "trialing"].includes(plan.status) ? now.getTime() < end + DAY // a day of slack for webhook lag
22	      : plan.status === "past_due" ? now.getTime() < end + cfg.plan.pastDueGraceDays * DAY
23	      : plan.status === "canceled" ? now.getTime() < end
24	      : false; // incomplete, incomplete_expired, unpaid, paused
25	    if (ok) tier = plan.tier;
26	  }
27	  const o = input.override;
28	  if ((o === "katara" || o === "saka" || o === "all") && (!input.overrideUntil || input.overrideUntil.getTime() > now.getTime())) tier = maxTier(tier, o);
29	  return tier;
30	}
