36	function perMonth(kind: "initial" | "renew", monthlyCents: number, cfg: TokenConfig): number {
37	  if (!(monthlyCents > 0)) return 0;
38	  const r = cfg.grant[kind];
39	  return Math.round(clamp(round5(r.base + r.perUsd * (monthlyCents / 100)), r.min, r.max));
