44	/**
45	 * Tokens for a game-server purchase ("initial") or a paid renewal ("renewal").
46	 * `monthlyCents` = what the customer actually pays per month (after discounts, before tax).
47	 * A prepaid N-month term earns the per-month renewal amount for each extra month, capped.
48	 */
49	export function serverGrant(kind: "initial" | "renewal", monthlyCents: number, termMonths: number, cfg: TokenConfig): ServerGrant {
50	  const months = clamp(Math.round(termMonths || 1), 1, cfg.grant.termMonthsCap);
51	  const ini = perMonth("initial", monthlyCents, cfg);
52	  const ren = perMonth("renew", monthlyCents, cfg);
53	  const tokens = kind === "initial" ? (ini ? ini + ren * (months - 1) : 0) : ren * months;
54	  const expiresInDays = Math.max(cfg.grant.expiryDays, Math.round(termMonths || 1) * 31 + 30);
55	  return { tokens, initialPerMonth: ini, renewPerMonth: ren, months, expiresInDays };
56	}
