58	/** The checkout line: "Includes N Cyrus tokens (+M every renewal)". */
59	export function checkoutLine(monthlyCents: number, termMonths: number, cfg: TokenConfig): { initial: number; renewal: number; text: string } | null {
60	  const i = serverGrant("initial", monthlyCents, termMonths, cfg);
61	  const r = serverGrant("renewal", monthlyCents, termMonths, cfg);
62	  if (!i.tokens) return null;
63	  return { initial: i.tokens, renewal: r.tokens, text: `Includes ${fmt(i.tokens)} Cyrus tokens (+${fmt(r.tokens)} every renewal) · Beta, Minecraft Java` };
