80	/**
81	 * Live-test fix (C1): what a build HOLDS. The reserve table's range, raised to the planned estimate in tokens
82	 * (lib/cyrus/planner/estimate.ts, +20% headroom on the high end) so the real spend rarely exceeds the hold: the first
83	 * live Yakko build held 250 (the table's simple high) and spent 431. Without an estimate: the table, unchanged.
84	 */
85	export function holdRange(model: CyrusModelId, complexity: Complexity, cfg: TokenConfig, usd?: readonly [number, number]): [number, number] {
86	  const t = reserveRange(model, complexity, cfg);
87	  if (!usd) return t;
88	  const lo = tokensForCost(usd[0], model, cfg);
89	  const hi = Math.ceil(tokensForCost(usd[1], model, cfg) * 1.2);
90	  return [Math.max(t[0], lo), Math.max(t[1], hi, lo)];
91	}
