93	/** Pre-build estimate shown in the composer: the [typical, high] token range. */
94	export function estimateTokens(text: string, model: CyrusModelId, cfg: TokenConfig): { complexity: Complexity; low: number; high: number } {
95	  const complexity = complexityOf(text);
96	  const [low, high] = reserveRange(model, complexity, cfg);
97	  return { complexity, low, high };
98	}
