100	/**
101	 * How much to hold for a build: the high end of the range, or everything the account has
102	 * when that is less but still covers the typical cost. null = not enough to start.
103	 */
104	export function reserveAmount(available: number, range: [number, number]): number | null {
105	  if (available >= range[1]) return range[1];
106	  if (available >= range[0]) return available;
107	  return null;
108	}
