110	/** Real AI cost -> tokens. 0 when nothing reached the AI. */
111	export function tokensForCost(costUsd: number, model: CyrusModelId, cfg: TokenConfig): number {
112	  if (!(costUsd > 0)) return 0;
113	  return Math.max(cfg.minSpend, Math.ceil(costUsd * cfg.tokensPerUsd * (cfg.mult[model] ?? 1) - 1e-9));
114	}
