116	export type SettleInput = { status: string; errorCode: string | null; costUsd: number; model: CyrusModelId; freeFailuresUsed: number };
117	export type SettleDecision = { charge: number; reason: "succeeded" | "refused" | "cancelled" | "failed_free" | "failed_partial" | "failed_over_limit" | "failed_infra" };
118	
119	/** Cyrus capacity: failures that are capacity/AI-backend outages on OUR side (the AI was busy or rate-limited after the
120	 *  automatic retries, or no builder could take the build). Never charged and never counted against the free failures. */
121	export const INFRA_FAILURE_CODES: readonly string[] = ["ai_unavailable", "capacity"];
122	
123	/** What a finished build costs. The charge is NOT capped at the reserve; the ledger caps it at the balance. */
124	export function settleCharge(i: SettleInput, cfg: TokenConfig): SettleDecision {
125	  const full = tokensForCost(i.costUsd, i.model, cfg);
126	  if (i.status === "succeeded") return { charge: full, reason: "succeeded" };
127	  if (i.errorCode === "refused") return { charge: cfg.chargeRefused ? full : 0, reason: "refused" };
128	  if (i.errorCode === "cancelled") return { charge: cfg.chargeCancelled ? full : 0, reason: "cancelled" };
129	  if (i.errorCode && INFRA_FAILURE_CODES.includes(i.errorCode)) return { charge: 0, reason: "failed_infra" };
130	  if (i.freeFailuresUsed >= cfg.freeFailures) return { charge: full, reason: "failed_over_limit" };
131	  const part = Math.ceil((full * cfg.failedChargePct) / 100);
132	  return part > 0 ? { charge: part, reason: "failed_partial" } : { charge: 0, reason: "failed_free" };
133	}
