135	export function dailyCapFor(accountCreatedAt: Date, now: Date, cfg: TokenConfig): number {
136	  return now.getTime() - accountCreatedAt.getTime() < cfg.newAccountDays * DAY ? Math.min(cfg.newAccountDailyCap, cfg.dailyCap) : cfg.dailyCap;
137	}
