143	/**
144	 * Tokens for one paid plan invoice.
145	 *  - subscription_create / subscription_cycle: the tier's full monthly amount (they stack).
146	 *  - subscription_update (an upgrade's proration): tokens in proportion to the money collected,
147	 *    at the new tier's rate, never more than one month of the new tier.
148	 */
149	export function planInvoiceTokens(i: { billingReason: string | null; amountPaidCents: number; tier: PlanTier; priceCents?: number | null }, cfg: TokenConfig): number {
150	  if (!(i.amountPaidCents > 0)) return 0;
151	  const monthly = cfg.plan.tokens[i.tier];
152	  if (i.billingReason === "subscription_create" || i.billingReason === "subscription_cycle") return monthly;
153	  // The proration rate is the plan's REAL Stripe price when known (the Setting is the fallback).
154	  const price = i.priceCents && i.priceCents > 0 ? i.priceCents : cfg.plan.cents[i.tier];
155	  if (i.billingReason === "subscription_update") return Math.min(monthly, Math.round((i.amountPaidCents / price) * monthly));
156	  return 0;
157	}
