159	/** A plan month's tokens expire `rolloverMonths` months (31-day months) after they were granted. */
160	export function planLotExpiry(grantedAt: Date, cfg: TokenConfig): Date {
161	  return new Date(grantedAt.getTime() + Math.round(cfg.plan.rolloverMonths * 31) * DAY);
