172	/** Plan tier of a Stripe price lookup key: cyrus_plan_<tier>_v1. */
173	export const PLAN_LOOKUP_KEY = (tier: PlanTier) => `cyrus_plan_${tier}_v1`;
174	export function tierFromLookupKey(k: string | null | undefined): PlanTier | null {
175	  const m = /^cyrus_plan_(katara|saka|all)_v\d+$/.exec(k || "");
176	  return m ? (m[1] as PlanTier) : null;
