179	/** Recommended worst-case margin per plan (all tokens burnt at multiplier 1, Stripe 2.9% + 30c). */
180	export function planMargin(tier: PlanTier, cfg: TokenConfig): { priceUsd: number; aiCostUsd: number; stripeFeeUsd: number; marginUsd: number; marginPct: number } {
181	  const priceUsd = cfg.plan.cents[tier] / 100;
182	  const aiCostUsd = cfg.plan.tokens[tier] / cfg.tokensPerUsd;
183	  const stripeFeeUsd = priceUsd * 0.029 + 0.3;
184	  const marginUsd = priceUsd - aiCostUsd - stripeFeeUsd;
185	  return { priceUsd, aiCostUsd, stripeFeeUsd, marginUsd, marginPct: priceUsd ? marginUsd / priceUsd : 0 };
186	}

  1	// CYRUS SIDE: the plan + token ENTITLEMENT mirrored from Nxeon, the payment provider (Katara / Saka / Yakko plans and
  2	// token packs are Nxeon products). Flag CYRUS_ENTITLEMENT_MIRROR=1 (off = nothing here runs; tierOf reads the plan row
  3	// exactly as before).
  4	//   apply      entitlement.changed (signed webhook, lib/cyrus/bridge/platform-events.ts) or a pulled snapshot: the plan
  5	//              becomes the mirrored CyrusPlan row (stripeSubscriptionId "nxeon:<user>"), older versions are ignored;
  6	//              wallet purchases are credited once by idemKey (the SAME key the direct path uses), refunds/chargebacks
  7	//              take back that lot's unspent tokens (applyPurchaseEvent).
  8	//   read       tierOf -> gateMirroredPlan: a 60 s in-process cache; past it, the mirror must have been CONFIRMED by
  9	//              Nxeon within CYRUS_ENTITLEMENT_MAX_AGE_H (default 36 h), else Cyrus pulls a fresh snapshot through the
 10	//              Platform API; if that fails too the plan counts as unknown = no paid plan (FAIL CLOSED).
 11	//   reconcile  reconcileEntitlements(): re-pull every mirrored user not confirmed in 12 h (worker sweep, daily cadence).
 12	// HOST SEAM: Nxeon is reached only through host.platform.
 13	import { cyrusDb as db } from "../db";
 14	import { getHost } from "../host";
 15	import { loadTokenConfig } from "./config";
 16	import { topupTokens } from "./economy";
 17	import { applyPurchaseEvent, purchaseEnvelope } from "./purchase";
 18	
 19	type Env = Record<string, string | undefined>;
 20	export const entitlementMirrorEnabled = (env: Env = process.env) => env.CYRUS_ENTITLEMENT_MIRROR === "1";
 21	const maxAgeMs = (env: Env = process.env) => Math.max(1, Math.min(24 * 14, Number(env.CYRUS_ENTITLEMENT_MAX_AGE_H) || 36)) * 3600_000;
 22	export const CACHE_TTL_MS = 60_000;
 23	export const MIRROR_PREFIX = "nxeon:";
 24	
 25	/** The wire shape (docs/api/nxeon-platform-v1.openapi.yaml components.schemas.Entitlement). */
 26	export type MirrorEntitlement = {
 27	  subject: string; version: number; issuedAt: string;
 28	  plan: { tier: "katara" | "saka" | "all" | null; status: "active" | "trialing" | "past_due" | "canceled" | "unpaid" | "none"; periodEnd: string | null; cancelAtPeriodEnd: boolean; product: string | null };
 29	  purchases: { idemKey: string; tokens: number | null; cents: number; method: "wallet" | "card"; at: string; refundedCents: number; chargeback: boolean }[];
 30	  partner: { code: string; firstPaymentPct: number; recurringPct: number } | null;
 31	  /** r51 storage add-on wallet charges (optional) */
 32	  storage?: { idemKey: string; gb: number; cents: number; at: string; refundedCents: number }[];
 33	  /** D-63/D-64 (optional, informational): the plan's game slots (0 = unlimited) and included GB. Cyrus enforces from
 34	   *  its own settings; this only lets a client show them. */
 35	  limits?: { games: number; storageGb: number };
 36	};
 37	
 38	const IDEM_RE = /^[A-Za-z0-9:_-]{6,160}$/;
 39	export function parseEntitlement(x: unknown): MirrorEntitlement | null {
 40	  const e = x as MirrorEntitlement;
 41	  if (!e || typeof e !== "object" || typeof e.subject !== "string" || !/^[A-Za-z0-9_:.-]{4,128}$/.test(e.subject) || !Number.isInteger(e.version) || e.version < 0) return null;
 42	  if (!e.plan || !["katara", "saka", "all", null].includes(e.plan.tier) || !["active", "trialing", "past_due", "canceled", "unpaid", "none"].includes(e.plan.status)) return null;
 43	  if (e.plan.periodEnd !== null && Number.isNaN(Date.parse(e.plan.periodEnd))) return null;
 44	  if (!Array.isArray(e.purchases) || e.purchases.length > 1000) return null;
 45	  for (const p of e.purchases) {
 46	    if (!p || !IDEM_RE.test(p.idemKey) || !Number.isInteger(p.cents) || p.cents <= 0 || p.cents > 10_000_000 || !Number.isInteger(p.refundedCents) || p.refundedCents < 0) return null;
 47	    if (p.tokens !== null && (!Number.isInteger(p.tokens) || p.tokens < 0 || p.tokens > 100_000_000)) return null;
 48	    // a purchase must belong to the subject (wallet references embed the user id)
 49	    if (p.idemKey.startsWith("cwt:") && !p.idemKey.startsWith(`cwt:${e.subject}:`)) return null;
 50	  }
 51	  if (e.storage !== undefined) {
 52	    if (!Array.isArray(e.storage) || e.storage.length > 1000) return null;
 53	    for (const s of e.storage) {
 54	      if (!s || typeof s.idemKey !== "string" || !s.idemKey.startsWith(`cst:${e.subject}:g`) || !IDEM_RE.test(s.idemKey) || !Number.isInteger(s.gb) || s.gb < 0 || !Number.isInteger(s.cents) || s.cents < 0 || s.cents > 10_000_000 || !Number.isInteger(s.refundedCents) || s.refundedCents < 0 || Number.isNaN(Date.parse(s.at))) return null;
 55	    }
 56	  }
 57	  if (e.limits !== undefined && (!e.limits || typeof e.limits !== "object" || !Number.isInteger(e.limits.games) || e.limits.games < 0 || e.limits.games > 1000 || !Number.isFinite(e.limits.storageGb) || e.limits.storageGb < 0 || e.limits.storageGb > 100_000)) return null;
 58	  return e;
 59	}
 60	
 61	const cache = new Map<string, number>();
 62	export function clearEntitlementCacheForTests() { cache.clear(); }
 63	
 64	export type ApplyEntitlementResult = { plan: "applied" | "stale" | "confirmed"; credited: number; reversed: number };
 65	
 66	/** Idempotent. Older versions never overwrite newer ones (they still CONFIRM the mirror is current). */
 67	export async function applyEntitlement(raw: unknown, now = new Date()): Promise<ApplyEntitlementResult> {
 68	  const e = parseEntitlement(raw);
 69	  if (!e) throw new Error("invalid entitlement");
 70	  const out: ApplyEntitlementResult = { plan: "confirmed", credited: 0, reversed: 0 };
 71	  const cur = await db.cyrusPlan.findUnique({ where: { userId: e.subject } });
 72	  const mirrored = !cur || cur.stripeSubscriptionId.startsWith(MIRROR_PREFIX);
 73	  const curVersion = cur?.lastSyncAt?.getTime() ?? -1;
 74	  if (mirrored && e.version > curVersion) {
 75	    const data = {
 76	      stripeCustomerId: "nxeon", stripeSubscriptionId: `${MIRROR_PREFIX}${e.subject}`,
 77	      tier: e.plan.tier ?? "katara", priceTier: e.plan.tier ?? "katara",
 78	      // a plan-less entitlement is stored as status "none": effectiveTier gives it no paid tier
 79	      status: e.plan.tier ? e.plan.status : "none",
 80	      currentPeriodEnd: e.plan.periodEnd ? new Date(e.plan.periodEnd) : null, cancelAtPeriodEnd: e.plan.cancelAtPeriodEnd,
 81	      endedAt: e.plan.status === "canceled" && e.plan.periodEnd ? new Date(e.plan.periodEnd) : null,
 82	      livemode: true, lastSyncAt: new Date(e.version),
 83	    };
 84	    await db.cyrusPlan.upsert({ where: { userId: e.subject }, create: { userId: e.subject, ...data }, update: data });
 85	    out.plan = "applied";
 86	  } else if (mirrored && cur) {
 87	    // same or older version: touch the row so updatedAt records that Nxeon confirmed it (the freshness rule)
 88	    await db.cyrusPlan.update({ where: { userId: e.subject }, data: { lastSyncAt: cur.lastSyncAt } });
 89	    out.plan = e.version < curVersion ? "stale" : "confirmed";
 90	  } else out.plan = "stale"; // a real (own-Stripe) plan row is never overwritten by the mirror
 91	  const cfg = e.purchases.length ? await loadTokenConfig() : null;
 92	  for (const p of e.purchases) {
 93	    const row = await db.cyrusTokenLedger.findUnique({ where: { idemKey: p.idemKey }, select: { id: true } });
 94	    const refunded = p.chargeback ? p.cents : Math.min(p.cents, p.refundedCents);
 95	    const tokens = p.tokens ?? topupTokens(p.cents, cfg!);
 96	    const data = { idemKey: p.idemKey, kind: "topup" as const, method: p.method, tokens, cents: p.cents, expiresAt: new Date(Date.parse(p.at) + cfg!.topup.expiryDays * 86_400_000).toISOString(), note: `Top-up $${(p.cents / 100).toFixed(2)} (${p.method}, from Nxeon)` };
 97	    if (!row) {
 98	      // fully refunded before it was ever credited (e.g. the compensating refund) -> nothing to credit
 99	      if (refunded >= p.cents) continue;
100	      const r = await applyPurchaseEvent(purchaseEnvelope("purchase.completed", e.subject, data, now));
101	      if (r.applied) out.credited += r.tokens;
102	    }
103	    // a refund already taken back on this side (refundWalletTopup, a Stripe refund) is not taken twice
104	    const priorRevoke = row ? await db.cyrusTokenLedger.findFirst({ where: { kind: "revoke", sourceRef: row.id }, select: { id: true } }) : null;
105	    if (refunded > 0 && !priorRevoke && (row || !(refunded >= p.cents))) {
106	      const r = await applyPurchaseEvent(purchaseEnvelope("purchase.refunded", e.subject, { ...data, refundedCents: refunded }, now));
107	      if (r.applied) out.reversed += r.tokens;
108	    }
109	  }
110	  // r51: storage add-on charges the mirror has not applied yet (lost apply, dead webhook): once, by idemKey
111	  if (e.storage?.length) {
112	    const { applyMirroredStorageCharge } = await import("../storage/addon");
113	    for (const s of e.storage) await applyMirroredStorageCharge(e.subject, s, now);
114	  }
115	  cache.set(e.subject, now.getTime());
116	  return out;
117	}
