119	/** Pull one user's snapshot from Nxeon and apply it. false when there is no Platform API or it failed. */
120	export async function pullEntitlement(userId: string, now = new Date()): Promise<boolean> {
121	  const p = getHost().platform;
122	  if (!p) return false;
123	  try { await applyEntitlement(await p.as(userId).entitlements(), now); return true; }
124	  catch (e) { console.error("[cyrus-entitlement] pull failed", userId, (e as Error).message); return false; }
125	}
