127	/** The fail-closed read rule tierOf applies to the plan row while the mirror is on. */
128	export async function gateMirroredPlan<P extends { stripeSubscriptionId: string; updatedAt: Date } | null>(userId: string, plan: P, env: Env = process.env, now = new Date()): Promise<P | null> {
129	  if (!entitlementMirrorEnabled(env)) return plan;
130	  // a plan this app bills itself (own Stripe, or Cyrus still inside Nxeon) is authoritative here: never gated
131	  if (plan && !plan.stripeSubscriptionId.startsWith(MIRROR_PREFIX)) return plan;
132	  const t = now.getTime();
133	  const hit = cache.get(userId);
134	  if (hit !== undefined && t - hit < CACHE_TTL_MS) return plan;
135	  if (plan && t - plan.updatedAt.getTime() < maxAgeMs(env)) { cache.set(userId, t); return plan; }
136	  // unknown or stale: one pull; failure = no paid plan
137	  if (await pullEntitlement(userId, now)) {
138	    const fresh = await db.cyrusPlan.findUnique({ where: { userId } });
139	    return (fresh && fresh.stripeSubscriptionId.startsWith(MIRROR_PREFIX) ? fresh : null) as P | null;
140	  }
141	  return null;
142	}
