144	/** Reconciliation (worker, flag on): re-pull every mirrored user not confirmed within 12 h. */
145	export async function reconcileEntitlements(o: { limit?: number; now?: Date } = {}, env: Env = process.env): Promise<{ checked: number; pulled: number; failed: number }> {
146	  if (!entitlementMirrorEnabled(env) || !getHost().platform) return { checked: 0, pulled: 0, failed: 0 };
147	  const now = o.now ?? new Date();
148	  const rows = await db.cyrusPlan.findMany({ where: { stripeSubscriptionId: { startsWith: MIRROR_PREFIX }, updatedAt: { lt: new Date(now.getTime() - 12 * 3600_000) } }, select: { userId: true }, take: o.limit ?? 200, orderBy: { updatedAt: "asc" } });
149	  let pulled = 0, failed = 0;
150	  for (const r of rows) if (await pullEntitlement(r.userId, now)) pulled++; else failed++;
151	  return { checked: rows.length, pulled, failed };
152	}
153	// Worker sweep for the Cyrus token economy (worker/index.ts "cyrus-tokens", every 5 min).
154	//  1. Settle holds whose build already finished (a settle that failed in the request path).
155	//  2. A hold whose build row vanished, or that is older than the build service's own
156	//     2 h staleness limit, is released (never left reserved forever).
157	//  3. Expire due lots (keeps the admin liability figure honest).
158	//  4. Reconcile active plans with Stripe at most hourly (covers a webhook that never came).
159	import { cyrusDb as db } from "../db";
160	import { getHost } from "../host";
161	
162	import { settleBuildTokens } from "./builds";
163	import { expireDueLots, settleReservation } from "./ledger";
164	import { reconcileSubscription } from "./billing";
165	
166	// Stripe is the host's (host.billing.stripe); same rule as lib/stripe stripeConfigured inside Nxeon.
167	const stripeConfigured = () => !!getHost().billing.stripe?.configured();
168	
169	const STALE_MS = 3 * 60 * 60 * 1000;
170	
171	let lastCardReconcile = 0;
172	export async function sweepCyrusTokens(now = new Date()): Promise<{ settled: number; released: number; expired: number; reconciled: number }> {
173	  let settled = 0, released = 0, reconciled = 0;
174	  const held = await db.cyrusTokenReservation.findMany({ where: { status: "held" }, take: 200, orderBy: { createdAt: "asc" } });
175	  if (held.length) {
176	    const builds = await db.modBuild.findMany({ where: { id: { in: held.map((h) => h.buildId) } }, select: { id: true, userId: true, status: true, errorCode: true, costUsd: true, cyrus: true } });
177	    const byId = new Map(builds.map((b) => [b.id, b]));
178	    for (const h of held) {
179	      const b = byId.get(h.buildId);
180	      try {
181	        if (b && (b.status === "succeeded" || b.status === "failed")) { await settleBuildTokens(b, now); settled++; }
182	        else if ((!b && now.getTime() - h.createdAt.getTime() > 120_000) || now.getTime() - h.createdAt.getTime() > STALE_MS) { await settleReservation({ buildId: h.buildId, charge: 0, reason: "stale", now }); released++; }
183	      } catch (e) { console.error("[cyrus-tokens] sweep settle", h.buildId, (e as Error).message); }
184	    }
185	  }
186	  const expired = await expireDueLots(undefined, now).catch(() => 0);
187	  if (stripeConfigured()) {
188	    const due = await db.cyrusPlan.findMany({
189	      // mirrored plans (r38, "nxeon:<user>") belong to Nxeon's Stripe, never this one
190	      where: { endedAt: null, NOT: { stripeSubscriptionId: { startsWith: "nxeon:" } }, OR: [{ lastSyncAt: null }, { lastSyncAt: { lt: new Date(now.getTime() - 60 * 60_000) } }] },
191	      take: 25,
192	    });
193	    for (const p of due) {
194	      try { await reconcileSubscription(p.stripeSubscriptionId); reconciled++; } catch (e) { console.error("[cyrus-tokens] reconcile", p.userId, (e as Error).message); }
195	    }
196	  }
197	  // r44: card top-ups on the event path whose event never landed (CYRUS_PURCHASE_EVENTS only; at most every 30 min)
198	  if (process.env.CYRUS_PURCHASE_EVENTS === "1" && now.getTime() - lastCardReconcile > 30 * 60_000) {
199	    lastCardReconcile = now.getTime();
200	    const r = await (await import("./billing")).reconcileCardTopupSessions().catch((e) => { console.error("[cyrus-tokens] card top-up reconcile", (e as Error).message); return null; });
201	    if (r) reconciled += r.credited;
202	  }
203	  // r38 entitlement mirror (standalone Cyrus, CYRUS_ENTITLEMENT_MIRROR=1): re-pull plans Nxeon has not confirmed in 12 h
204	  if (process.env.CYRUS_ENTITLEMENT_MIRROR === "1") {
205	    const r = await (await import("./entitlement")).reconcileEntitlements({ now, limit: 50 }).catch((e) => { console.error("[cyrus-tokens] entitlement reconcile", (e as Error).message); return null; });
206	    if (r) reconciled += r.pulled;
