241	export async function adminGrantTokens(fd: FormData) {
242	  const admin = await guard();
243	  const u = await targetUser(fd.get("user"));
244	  const amount = Math.floor(Number(fd.get("amount")));
245	  const note = String(fd.get("note") ?? "").trim().slice(0, 200);
246	  if (!u) back("err=" + encodeURIComponent("No such account."));
247	  if (!(amount > 0 && amount <= 1_000_000)) back("err=" + encodeURIComponent("Amount must be 1 to 1,000,000."));
248	  const cfg = await loadTokenConfig();
249	  const days = Math.floor(Number(fd.get("days"))) || cfg.adminGrantExpiryDays;
250	  const r = await creditTokens({
251	    userId: u!.id, amount, kind: "grant", source: "admin", sourceRef: admin.id,
252	    // A fresh key per submit; a double-submit within the same request id is prevented by the form token.
253	    idemKey: `admin:${String(fd.get("token") || randomBytes(8).toString("hex"))}`,
254	    expiresAt: new Date(Date.now() + Math.min(3650, Math.max(1, days)) * DAY),
255	    note: note || "Admin grant", actorId: admin.id,
256	  });
257	  await getHost().audit.append({ userId: admin.id, action: "cyrus.tokens.grant", detail: `${u!.email} +${r.amount} ${note}`.slice(0, 500) }).catch(() => {});
258	  back(r.created ? `ok=${encodeURIComponent(`Granted ${r.amount} tokens to ${u!.email}.`)}` : "ok=" + encodeURIComponent("Already applied."));
259	}
