296	export async function adminSaveTokenSettings(fd: FormData) {
297	  const admin = await settingsGuard();
298	  const changed: string[] = [];
299	  for (const k of TOKEN_SETTING_KEYS) {
300	    if (k === "cyrus_tok_live") continue; // r40 launch pair: only /admin/cyrus/flags changes it, together with cyrus_studio_public_enabled
301	    if (!fd.has(k)) continue;
302	    const v = String(fd.get(k) ?? "").trim();
303	    if (k === "cyrus_tok_reserve_table") { try { JSON.parse(v); } catch { back("err=" + encodeURIComponent("Reserve table must be valid JSON.")); } }
304	    if (v && k in TOKEN_ENUMS && !(TOKEN_ENUMS as Record<string, readonly string[]>)[k].includes(v)) back("err=" + encodeURIComponent(`${k} must be one of: ${(TOKEN_ENUMS as Record<string, readonly string[]>)[k].join(", ")}.`));
305	    // inline-editable keys get the catalog's range checks (a JSON/price-id key is edited here and checked above)
306	    if (v && cyrusSettingDef(k) && !cyrusSettingDef(k)!.editAt) { const ok = validateSettingValue(k, v); if (!ok.ok) back("err=" + encodeURIComponent(`${k}: ${ok.error}`)); }
307	    const stored = await getHost().settings.readStored([k]);
308	    const has = k in stored;
309	    const def = CYRUS_TOKEN_DEFAULTS[k as TokenSettingKey];
310	    if (v === "" || v === def) { if (has) { await getHost().settings.clearStored(k); changed.push(`${k}=default`); } continue; }
311	    if (has && stored[k] === v) continue;
312	    await getHost().settings.writeStored(k, v);
313	    changed.push(`${k}=${v.slice(0, 60)}`);
314	  }
315	  clearTokenConfigCache();
316	  if (changed.length) await getHost().audit.append({ userId: admin.id, action: "cyrus.tokens.settings", detail: changed.join(" ").slice(0, 1000) }).catch(() => {});
317	  back(`ok=${encodeURIComponent(changed.length ? `Saved ${changed.length} setting(s).` : "No changes.")}`);
318	}
319	// Who takes part in the Cyrus token economy. Server only.
320	//
321	// Until the owner launches (Setting cyrus_tok_live = true) ONLY private-preview accounts
322	// (lib/preview-access.ts feature "modbuilder", the same list that can open Cyrus) earn
323	// grants, see the checkout line or the balance. Everyone else: nothing happens and
324	// nothing is shown. Fails closed (a settings/DB error = not active).
325	import { getHost } from "../host";
326	import { cyrusDb as db } from "../db";
327	import { loadTokenConfig, type TokenConfig } from "./config";
328	import { effectiveTier } from "./economy";
329	import type { TokenTier } from "./config";
330	
331	/**
332	 * In the token economy: the owner has launched it for everyone (cyrus_tok_live), the account is on the
333	 * private preview list, OR the account has EVER held tokens (an account row exists). Once an account has had
334	 * tokens it stays in the economy for good, even at a zero balance, so its balance stays pinned in the portal.
335	 */
336	export async function tokensActiveFor(user: { id?: string | null; email?: string | null } | null | undefined, cfg?: TokenConfig): Promise<boolean> {
337	  if (!user?.email) return false;
338	  try {
339	    const c = cfg ?? (await loadTokenConfig());
340	    if (c.live) return true;
341	    if (await getHost().access.isPreviewUser(user, "modbuilder")) return true;
342	    if (user.id) return !!(await db.cyrusTokenAccount.findUnique({ where: { userId: user.id }, select: { userId: true } }));
343	    return false;
344	  } catch {
345	    return false;
346	  }
347	}
348	
349	export async function tokensActiveForUserId(userId: string, cfg?: TokenConfig): Promise<boolean> {
350	  const u = await getHost().users.get(userId).catch(() => null);
351	  return tokensActiveFor(u, cfg);
352	}
353	
354	/** The account's model entitlement now (plan + admin override). */
355	export async function tierOf(userId: string, cfg?: TokenConfig, now = new Date()): Promise<TokenTier> {
356	  const c = cfg ?? (await loadTokenConfig());
357	  const [plan, acct] = await Promise.all([
358	    db.cyrusPlan.findUnique({ where: { userId } }),
359	    db.cyrusTokenAccount.findUnique({ where: { userId }, select: { tierOverride: true, tierOverrideUntil: true } }),
360	  ]);
361	  // CYRUS_ENTITLEMENT_MIRROR (standalone Cyrus): a mirrored plan Nxeon has not confirmed recently counts as none (fail closed)
362	  const gated = process.env.CYRUS_ENTITLEMENT_MIRROR === "1" ? await (await import("./entitlement")).gateMirroredPlan(userId, plan, process.env, now) : plan;
363	  return effectiveTier({ plan: gated, override: acct?.tierOverride, overrideUntil: acct?.tierOverrideUntil, now, cfg: c });
364	}

