// Cyrus' own tables: Nxeon's client until CYRUS_DATABASE_URL names a separate database (data split), then one
// dedicated client (kept on globalThis so dev reloads do not leak connections).
const g = globalThis as unknown as { cyrusSplitDb?: PrismaClient };
function cyrusTablesDb(): PrismaClient {
  const url = cyrusDatabaseUrl();
  if (!url) return db;
  // Typed through `unknown` on purpose: `new PrismaClient({ datasources })` is a different generic instantiation of the
  // client, and letting TypeScript compare it structurally with PrismaClient cost ~1.1M types and 10 s per program,
  // which pushed `tsc` and the type check of `next build` past the heap limit (rc1, 2026-10-11). Runtime is unchanged.
  return (g.cyrusSplitDb ??= new PrismaClient({ datasources: { db: { url } } }) as unknown as PrismaClient);
}

