export async function handleExternalRefund(
  ch: Stripe.Charge,
  resolveUserId: (a: { stripeCustomer: string | null; paymentIntentId: string | null }) => Promise<string | null>,
): Promise<ExternalRefundResult> {
  // The event carries the charge; the refund list is the reliable source for the
  // newest refund (charge.refunds is not expanded on newer API versions).
  const refunds = await stripe().refunds.list({ charge: ch.id, limit: 5 });
  const latest = refunds.data[0];
  if (!latest) return "no-refund";

  // Our own admin refund marks what it creates; it already did the bookkeeping.
  if (latest.metadata?.nxeonRefund === "1") return "own-refund";

  const seen = await db.auditLog.findFirst({
    where: { action: "billing.refund.external", detail: { contains: latest.id } },
    select: { id: true },
  });
  if (seen) return "duplicate";

  const stripeCustomer = typeof ch.customer === "string" ? ch.customer : ch.customer?.id ?? null;
  const paymentIntentId = typeof ch.payment_intent === "string" ? ch.payment_intent : ch.payment_intent?.id ?? null;
  const userId =
    (ch.metadata as Record<string, string> | null)?.nxeonUserId ||
    (await resolveUserId({ stripeCustomer, paymentIntentId }).catch(() => null));
  const user = userId ? await db.user.findUnique({ where: { id: userId }, select: { id: true, email: true, name: true, stripePaymentMethodId: true } }) : null;

  const amount = money(latest.amount, latest.currency);
  if (!user) {
    // Still leave a trail: an unattributable refund is exactly what an admin should see.
    await db.auditLog.create({
      data: {
        userId: null,
        action: "billing.refund.external",
        detail: `${amount} refunded outside the app (Stripe ${latest.id}, charge ${ch.id}) — customer could not be matched; reconcile manually`,
      },
    });
    return "no-user";
  }

  const renewing = await db.server.findMany({
    where: { userId: user.id, autoRenew: true, status: { notIn: ["DELETING", "DELETED"] as any } },
    select: { hostname: true },
    take: 10,
  });
  const renewWarning =
    renewing.length > 0 && user.stripePaymentMethodId
      ? ` Auto-renew is still ON for ${renewing.map((s) => s.hostname).join(", ")} with a saved card — turn it off or the customer will be charged again at renewal.`
      : "";

  await db.auditLog.create({
    data: {
      userId: null,
      action: "billing.refund.external",
      detail:
        `user=${user.email} ${amount} refunded outside the app (Stripe ${latest.id}, charge ${ch.id}); ` +
        `not applied to any invoice — reconcile in admin. Fees are not refundable.${renewWarning}`,
    },
  });

  const admins = await db.user.findMany({ where: { role: "ADMIN" }, select: { id: true } });
  if (admins.length) {
    await db.notification.createMany({
      data: admins.map((a) => ({
        userId: a.id,
        title: `Refund issued outside the app: ${amount} to ${user.email}`,
        body:
          `Refunded in Stripe, not through the admin Refund control, so no invoice was updated and the customer wasn't ` +
          `told by our own flow. Mark the matching invoice refunded and check their servers.${renewWarning}`,
        href: `/admin/users/${user.id}`,
      })),
    });
  }

  // Tell the customer (best-effort; the audit row above is already the anchor).
  try {
    const { emails, sendMail } = await import("./mailer");
    const tpl = emails.refundIssued({ name: user.name, amount, destination: "card" });
    await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, template: tpl.template, userId: user.id, kind: "refund" });
  } catch (e) {
    console.error("[refund-sync] customer email failed", e);
  }
  return "handled";
}
