/**
 * Classify a retrieved session. Pure — no clock, no network, no database — so the
 * routing decision is unit-testable and identical for the redirect and the webhook.
 */
export function classifyCheckoutSession(
  session: Pick<Stripe.Checkout.Session, "metadata" | "payment_status"> &
    Partial<Pick<Stripe.Checkout.Session, "mode" | "status">>,
): CheckoutPurpose {
  const md = session.metadata ?? null;
  const userId = parseId(md?.nxeonUserId);

  // Hosting renewal-card SETUP (2026-10-07). Checked BEFORE the paid gate because a
  // setup session never has `payment_status: "paid"` — it moves no money
  // ("no_payment_required"). It counts only once Stripe says the setup itself is
  // `complete`, and only in `mode: "setup"`: the same key on a payment-mode session
  // is not something this codebase creates, so it is refused as unreadable rather
  // than guessed at.
  const hostSetupRaw = md?.nxeonHostOrderSetup;
  if (hostSetupRaw) {
    if (!userId) return { kind: "unpaid" };
    if (session.mode !== "setup") {
      return { kind: "unreadable", userId, detail: "nxeonHostOrderSetup on a non-setup session" };
    }
    if (session.status !== "complete") return { kind: "unpaid" };
    let p: Record<string, unknown>;
    try {
      p = JSON.parse(hostSetupRaw) as Record<string, unknown>;
    } catch {
      return { kind: "unreadable", userId, detail: "nxeonHostOrderSetup is not valid JSON" };
    }
    const planId = parseId(p?.planId);
    const idempotencyKey = parseId(p?.idempotencyKey);
    const dueCents = parseChargeCents(p?.dueCents);
    if (!planId || !idempotencyKey || dueCents === null) {
      return { kind: "unreadable", userId, detail: "nxeonHostOrderSetup is missing planId/idempotencyKey/dueCents" };
    }
    return {
      kind: "hostOrderSetup",
      userId,
      intent: {
        planId,
        idempotencyKey,
        dueCents,
        ipHash: typeof p.ipHash === "string" && p.ipHash ? p.ipHash : null,
