    const plan = await db.cyrusPlan.findUnique({ where: { userId: u.id } });
    assert.equal(plan?.tier, "katara"); assert.equal(plan?.status, "active");
    // A renewal stacks.
    state.invoices.push(inv("in_2", "sub_a", u.id, "katara", "subscription_cycle", 499, "pi_2"));
    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[1]));
