    await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_2", payment_intent: "pi_2", amount: 499, amount_refunded: 250 }));
    assert.equal(await bal(u.id), 1500 + 4501 - 376);
    // Then the rest of it.
