    await S.handleCyrusStripeEvent(ev("invoice.paid", state.invoices[4]));
    const b = await bal(u.id);
    assert.equal(b, 4 * 750 + 10000);
    for (const i of state.invoices) await S.handleCyrusStripeEvent(ev("invoice.paid", i));
