describe("r49 QA money journey (one account, both hosts)", { skip }, () => {
  it("plan from cyrus.my + pack from nxeon.cloud credit once; free server tokens; rollover; spend; refund + early delete reverse once", async () => {
    const u = await db.user.create({ data: { email: `qa49-${uniq()}@example.test`, passwordHash: "x", name: "QA journey", emailVerifiedAt: new Date() } });
    users.push(u.id);
    const cfg = await C.loadTokenConfig();
    const subId = `sub_${uniq()}`;
    const state = { subs: { [subId]: sub(subId, u.id, "katara") } as Record<string, Rec>, invoices: [] as Rec[], sessions: {} as Record<string, Rec>, created: [] as Rec[] };
    S.setCyrusStripeForTests(fakeStripe(state) as never);

    // 1. plan checkout opened on cyrus.my returns to cyrus.my; pack checkout opened on nxeon.cloud returns there
    assert.equal((await S.openPlanCheckout(u, "katara", { returnBase: "https://cyrus.my" })).ok, true);
    assert.match(String(state.created[0].return_url), /^https:\/\/cyrus\.my\/api\/cyrus\/tokens\/return\?session_id=/);
    // top-ups may require a paid product first (placeholder rule): the plan below satisfies it, so pay the plan first
    const i1 = inv(`in_${uniq()}`, subId, u.id, "subscription_create"); state.invoices.push(i1);
    for (let k = 0; k < 3; k++) await S.handleCyrusStripeEvent(ev("invoice.paid", i1));
    await S.handleCyrusStripeEvent(ev("customer.subscription.created", state.subs[subId]));
    const planTokens = cfg.plan.tokens.katara;
    assert.equal(await invariant(u.id), planTokens, "plan credited once across 3 replays");

    assert.equal((await S.openTopupCheckout(u, 1000, { returnBase: "https://nxeon.cloud" })).ok, true);
    assert.match(String(state.created[1].return_url), /^https:\/\/nxeon\.cloud\/api\/cyrus\/tokens\/return\?session_id=/);
    const md = state.created[1].metadata as Record<string, string>;
    const cs = { id: `cs_test_${uniq()}`, mode: "payment", payment_status: "paid", amount_total: 1000, livemode: false, payment_intent: "pi_pack", created: Math.floor(Date.now() / 1000), metadata: md };
    state.sessions[cs.id] = cs;
    await S.handleCyrusStripeEvent(ev("checkout.session.completed", cs));
    await S.handleCyrusStripeEvent(ev("checkout.session.completed", cs));
    await S.fulfilCyrusSession(cs.id); // the return leg on whichever host
    const packTokens = Number(md.cyrusTokens);
    assert.ok(packTokens > 0);
    assert.equal(await invariant(u.id), planTokens + packTokens, "pack credited once (2 webhooks + return leg)");

    // 2. free tokens: a Nxeon game server deploy + one renewal (placeholder amounts from config)
    const serverId = `srv_${uniq()}`;
    const g = await G.grantForGameServerPurchase({ userId: u.id, serverId, gameFamily: "minecraft", chargeCents: 3000, termMonths: 1 });
    const ini = cfg.grant.initial;
    assert.equal(g?.amount, Math.min(ini.max, Math.max(ini.min, Math.round(ini.base + ini.perUsd * 30))), "initial grant = placeholder formula");
    assert.equal((await G.grantForGameServerPurchase({ userId: u.id, serverId, gameFamily: "minecraft", chargeCents: 3000, termMonths: 1 }))?.created ?? false, false, "same server, same deploy: once");
    const ren = await G.grantForGameServerRenewal({ userId: u.id, serverId, gameFamily: "minecraft", netCents: 3000, months: 1, periodStart: new Date(Date.now() + 31 * DAY) });
    let expected = planTokens + packTokens + g!.amount + (ren?.amount ?? 0);
    assert.equal(await invariant(u.id), expected);

    // 3. plan renews: the month stacks and nothing from the plan expires while it is active
    const i2 = inv(`in_${uniq()}`, subId, u.id, "subscription_cycle"); state.invoices.push(i2);
    await S.handleCyrusStripeEvent(ev("invoice.paid", i2)); await S.handleCyrusStripeEvent(ev("invoice.paid", i2));
    expected += planTokens;
    assert.equal(await invariant(u.id), expected, "renewal stacked once");
    if (cfg.plan.rolloverMode === "while_active") assert.ok((await db.cyrusTokenLot.findMany({ where: { userId: u.id, source: "plan" } })).every((l) => l.expiresAt === null));

    // 4. spend through a build reservation (held, then settled)
    const build = await db.modBuild.create({ data: { userId: u.id, prompt: "qa journey", mcVersion: "1.21.11", status: "queued" } as never });
    const rv = await L.reserveTokens({ userId: u.id, buildId: build.id, model: "saka", need: 200, pick: (a) => (a >= 200 ? 200 : null), dailyCap: () => 1_000_000 });
    assert.equal(rv.ok, true, "reservation held");
    await L.settleReservation({ buildId: build.id, charge: 150, reason: "build" });
    expected -= 150;
    assert.equal(await invariant(u.id), expected, "settle charges 150, returns 50");

    // 5. pack refunded in full: only the pack's UNSPENT tokens come back off, once
    const lotPack = await db.cyrusTokenLot.findFirst({ where: { userId: u.id, source: "topup" } });
    const unspentPack = lotPack?.remaining ?? 0;
    for (let k = 0; k < 2; k++) await S.handleCyrusStripeEvent(ev("charge.refunded", { id: "ch_pack", payment_intent: "pi_pack", amount: 1000, amount_refunded: 1000 }));
    expected -= unspentPack;
    assert.equal(await invariant(u.id), expected, "refund reverses the pack's unspent tokens once");

    // 6. the server is deleted inside the clawback window: its unspent grant goes back, once
    const r1 = await G.reverseServerGrants({ userId: u.id, serverId, reason: "deleted" });
    const r2 = await G.reverseServerGrants({ userId: u.id, serverId, reason: "deleted" });
    assert.equal(r2.revoked, 0, "clawback idempotent");
    expected -= r1.revoked;
    assert.equal(await invariant(u.id), expected);
    assert.ok(expected >= 2 * planTokens - 150, "plan tokens survive the pack refund and the server clawback");
  });
  it("cumulative partial refunds (50% then 60%) take back at most 60% of the pack, once (re-audit C-L4)", async () => {
    const P = await import("../lib/cyrus/tokens/purchase.ts");
    const u = await db.user.create({ data: { email: `qa49r-${uniq()}@example.test`, passwordHash: "x", name: "QA refund" } });
    users.push(u.id);
    const k = `qa49:topup:${uniq()}`;
    const env = (type: "purchase.completed" | "purchase.refunded", refundedCents?: number) => ({ id: `pe_${uniq()}`, type, createdAt: new Date().toISOString(), subject: u.id, data: { idemKey: k, kind: "topup" as const, method: "card" as const, tokens: 1200, cents: 1000, expiresAt: null, note: "QA pack", ...(refundedCents !== undefined ? { refundedCents } : {}) } });
    assert.equal((await P.applyPurchaseEvent(env("purchase.completed"))).tokens, 1200);
    await P.applyPurchaseEvent(env("purchase.refunded", 500));
    await P.applyPurchaseEvent(env("purchase.refunded", 500)); // redelivery
    await P.applyPurchaseEvent(env("purchase.refunded", 600)); // Stripe's amount_refunded is cumulative
    assert.equal((await L.tokenSummary(u.id)).balance, 1200 - 720, "60% of 1200 back, not 100%");
  });
});

