describe("wallet top-up (one account, one wallet)", { skip }, () => {
  it("charges the wallet once and credits once, even when retried", async () => {
    const u = await mkUser(2000);
    const k = key();
    const r1 = await P.payTopupWithWallet(u, 1000, k);
    assert.equal(r1.state, "credited");
    assert.equal(r1.tokens, 1200);
    const r2 = await P.payTopupWithWallet(u, 1000, k);
    assert.equal(r2.state, "credited");
    assert.equal(await wallet(u.id), 1000);
    assert.equal(await tokens(u.id), 1200);
    assert.equal(await P.walletTopupStatus(u.id, k), "credited");
  });
  it("refuses without funds and debits nothing", async () => {
    const u = await mkUser(100);
    const r = await P.payTopupWithWallet(u, 1000, key());
    assert.equal(r.state, "insufficient_funds");
    assert.equal(await wallet(u.id), 100);
    assert.equal(await tokens(u.id), 0);
  });
  it("a failed credit refunds the wallet (honest failed state)", async () => {
    const u = await mkUser(1500);
    const base = H.getHost();
    process.env.CYRUS_PURCHASE_EVENTS = "1";
    const restore = H.setHost({ ...base, billing: { ...base.billing, wallet: base.billing.wallet, emitPurchase: async () => { throw new Error("down"); } } });
    try {
      const k = key();
      const r = await P.payTopupWithWallet(u, 1000, k);
      assert.equal(r.state, "failed");
      assert.equal(await wallet(u.id), 1500);
      assert.equal(await tokens(u.id), 0);
      assert.equal(await P.walletTopupStatus(u.id, k), "failed");
    } finally { restore(); delete process.env.CYRUS_PURCHASE_EVENTS; }
  });
  it("event path: pending until the signed event is applied; redelivery does not double-credit", async () => {
    const u = await mkUser(1000);
    const sent: import("../lib/cyrus/host/types.ts").PurchaseEnvelope[] = [];
    const base = H.getHost();
    process.env.CYRUS_PURCHASE_EVENTS = "1";
    const restore = H.setHost({ ...base, billing: { ...base.billing, wallet: base.billing.wallet, emitPurchase: async (e) => { sent.push(e); } } });
    try {
      const k = key();
      assert.equal((await P.payTopupWithWallet(u, 500, k)).state, "pending");
      assert.equal(await P.walletTopupStatus(u.id, k), "pending");
      assert.equal(await tokens(u.id), 0);
      // the receiver route, signed, twice
      process.env.CYRUS_PURCHASE_EVENTS_SECRET = SECRET;
      const { POST } = await import("../app/api/cyrus/purchase-events/route.ts");
      const { signPurchaseEvent } = await import("../lib/cyrus-client/purchase-events.ts");
      const post = async (e: (typeof sent)[0], sig?: string) => {
        const body = JSON.stringify(e), ts = String(Math.floor(Date.now() / 1000));
        return POST(new Request("http://x/api/cyrus/purchase-events", { method: "POST", body, headers: { "nxeon-webhook-id": e.id, "nxeon-webhook-timestamp": ts, "nxeon-signature": sig ?? signPurchaseEvent(SECRET, e.id, ts, body) } }));
      };
      assert.equal((await post(sent[0], "v1=00")).status, 401);
      assert.equal((await post({ ...sent[0], data: { ...sent[0].data, tokens: 999999 } }, "v1=bad")).status, 401);
      assert.equal((await post(sent[0])).status, 200);
      assert.equal(await tokens(u.id), 600);
      assert.equal((await post(sent[0])).status, 200); // duplicate id
      await P.applyPurchaseEvent(sent[0]); // and a direct redelivery
      assert.equal(await tokens(u.id), 600);
      assert.equal(await wallet(u.id), 500);
    } finally { restore(); delete process.env.CYRUS_PURCHASE_EVENTS; delete process.env.CYRUS_PURCHASE_EVENTS_SECRET; }
  });
  it("reconciliation credits a charge whose credit was lost", async () => {
    const u = await mkUser(1000);
    const k = key();
    const ref = P.walletRef(u.id, k);
    const c = await H.getHost().billing.wallet!.charge({ userId: u.id, cents: 500, description: "Cyrus tokens", reference: ref });
    assert.ok(c.ok);
    assert.equal(await P.walletTopupStatus(u.id, k), "pending");
    const r = await P.reconcileWalletTopups({ userId: u.id });
    assert.equal(r.credited, 1);
    assert.equal(await tokens(u.id), 600);
    assert.equal((await P.reconcileWalletTopups({ userId: u.id })).credited, 0);
    // the wallet charge itself is idempotent per reference
    const again = await H.getHost().billing.wallet!.charge({ userId: u.id, cents: 500, description: "Cyrus tokens", reference: ref });
    assert.deepEqual(again, { ok: true, replay: true });
    assert.equal(await wallet(u.id), 500);
  });
  it("a refund takes back unspent tokens and returns that share of money", async () => {
    const u = await mkUser(1000);
    const k = key();
    assert.equal((await P.payTopupWithWallet(u, 1000, k)).state, "credited");
    const r = await P.refundWalletTopup(u.id, k);
    assert.deepEqual(r, { ok: true, tokens: 1200, cents: 1000 });
    assert.equal(await tokens(u.id), 0);
    assert.equal(await wallet(u.id), 1000);
    assert.equal((await P.refundWalletTopup(u.id, k)).ok, false);
    assert.equal(await wallet(u.id), 1000);
  });
});

