// r44: the wallet button. One idempotency key per click (a retry of the SAME purchase reuses it), honest states.
async function payFromWallet(cents: number) {
  const label = "wallet"; setBusy(label); setErr(null); setMsg(null);
  const key = (globalThis.crypto?.randomUUID?.() ?? `${Date.now()}${Math.random()}`).replace(/[^A-Za-z0-9]/g, "").slice(0, 32).padEnd(16, "0");
  try {
    const r = await fetch("/api/cyrus/tokens/wallet", { method: "POST", headers: { "Content-Type": "application/json", "Idempotency-Key": key }, body: JSON.stringify({ cents }) });
    const j = await r.json().catch(() => ({})) as { state?: string; tokens?: number; error?: string };
    if (j.state === "credited") { setMsg(`${fmtTokens(j.tokens ?? 0)} tokens added from your Nxeon wallet.`); await cyrusTokens.refresh(); }
    else if (j.state === "pending") {
      setMsg("Paid from your wallet. Your tokens are on the way.");
      for (let i = 0; i < 5; i++) {
        await new Promise((res) => setTimeout(res, 2000));
        const s2 = await fetch(`/api/cyrus/tokens/wallet?key=${key}`, { cache: "no-store" }).then((x) => x.json()).catch(() => null) as { state?: string } | null;
        if (s2?.state === "credited") { setMsg("Tokens added from your Nxeon wallet."); await cyrusTokens.refresh(); break; }
        if (s2?.state === "failed") { setMsg(null); setErr("We couldn't add your tokens, so your wallet was refunded."); break; }
      }
    }
    else if (j.state === "insufficient_funds") setErr("Not enough in your Nxeon wallet. Add funds at Nxeon, then come back.");
    else setErr(j.error || "Couldn't pay from your wallet.");
  } catch { setErr("We couldn't reach Nxeon. Try again."); }
  setBusy(null);
}

